public class PlayerShooter : MonoBehaviour
{
    [SerializeField] private AudioSource _gunSound;
    [SerializeField] private ParticleSystem _muzzleFlash;

    private int _ammo = 30;

    public void Shoot()
    {
        if (_ammo <= 0) return;
        _ammo--;
        _gunSound.Play();
        _muzzleFlash.Play();
    }
}

/// <summary>
/// Aplica daño al jugador y verifica si debe morir.
/// </summary>
/// <param name="amount">Cantidad de daño recibido.</param>
/// <returns>True si el jugador muere tras recibir el daño.</returns>
public bool TakeDamage(int amount)
{
    _health -= amount;
    return _health <= 0;
}

